import fs from'node:fs';import cp from'node:child_process';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';
const[repo,out]=process.argv.slice(2),sha=b=>createHash('sha256').update(b).digest('hex'),blob=(pin,p)=>cp.execFileSync('git',['cat-file','blob',pin+':'+p],{cwd:repo,maxBuffer:32e6});
const specs=[['paid-match-nhsp-separate-event-writer-construction-20261015','ea7fe7b0f3cb3d566e0b95a0927916539d6035ba','nhsp-event-source.test.mjs',15],['paid-match-nhsp-current-native-basis-construction-20261015','5f79c0d2d810295f25415443c94eaf72b4a92eb9','basis-source.test.mjs',12],['paid-match-nhsp-negative-population-construction-20261015','b326d7033c0916217d16fde6c3b839f94a1f9ce9','negative-population-source.test.mjs',16]],base=i=>'docs/healthroster-build/proposals/'+specs[i][0]+'/';
function seal(){return specs.map(([dir,pin],i)=>{const raw=blob(pin,base(i)+'FROZEN_ARTIFACT_MANIFEST.json'),m=JSON.parse(raw);for(const e of [...m.artifacts,{file:'FROZEN_ARTIFACT_MANIFEST.json'}]){const b=blob(pin,base(i)+e.file);assert.deepEqual(b,fs.readFileSync(path.join(repo,base(i),e.file)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{dir,commit:pin,files:m.artifacts.length+1,manifest_sha256:sha(raw)};});}
fs.mkdirSync(out,{recursive:true});const before=seal();const parser=blob(specs[2][1],'docs/healthroster-build/proposals/a0-current-root-install2-forward/PINNED_A0_CURRENT_SOURCE_INDEX.mjs');assert.deepEqual(parser,fs.readFileSync(path.join(repo,'docs/healthroster-build/proposals/a0-current-root-install2-forward/PINNED_A0_CURRENT_SOURCE_INDEX.mjs')));const{functionEvents}=await import('data:text/javascript;base64,'+parser.toString('base64'));
let pins=0,owners=0,hunks=0;const proofs=[];
for(const[i,spec]of specs.entries()){const proofFile=i===1?'SOURCE_ADDITION_AND_INPUT_PINS.json':'COMPLETE_REVERSE_AND_INPUT_PINS.json',p=JSON.parse(blob(spec[1],base(i)+proofFile));proofs.push(p);for(const d of p.inputs){const raw=blob(d.commit,d.file),saved=blob(spec[1],base(i)+d.saved);assert.equal(saved.length,d.bytes);assert.equal(sha(saved),d.sha256);if(d.signature){assert.equal(raw.length,d.source_bytes);assert.equal(sha(raw),d.source_sha256);const matches=functionEvents(raw.toString()).events.filter(e=>e.id===d.signature);assert.equal(matches.length,1);assert.equal(sha(matches[0].definition),d.definition_sha256);assert.equal(sha(matches[0].body),d.body_sha256);assert.equal(saved.toString(),matches[0].definition+'\n');}else assert.deepEqual(saved,raw);pins++;}
 if(i===1){assert.equal(sha(blob(spec[1],base(i)+p.forward)),p.forward_sha256);continue;}
 const file=i===0?'forward/01_complete_projection_rows.sqlinc':'forward/02_complete_native_capture_movement.sqlinc';let text=blob(spec[1],base(i)+file).toString();assert.equal(sha(text),p.after_sha256);for(const h of [...p.hunks].reverse()){assert.equal(text.split(h.after).length,2);text=text.replace(h.after,()=>h.before);hunks++;}assert.equal(sha(text),p.before_sha256);if(i===0)assert.deepEqual(Buffer.from(text),blob(p.commit,p.source));else{const d=p.inputs.find(d=>d.signature===p.existing_owner_signature);assert(d);const e=functionEvents(blob(d.commit,d.file).toString()).events.find(e=>e.id===d.signature);assert.equal(text,e.definition+'\n');}owners++;
}
assert.equal(pins,24);assert.equal(owners,2);assert.equal(hunks,7);
const negative=proofs[2],core=blob(specs[2][1],base(2)+'forward/01_native_magnitude_core.sqlinc').toString();assert.equal(negative.extracted_block,negative.native_magnitude_block.replaceAll('v_m.canonical_pay_vector_json','p_pay_vector').replaceAll('v_m.canonical_charge_vector_json','p_charge_vector').replaceAll('v_m.source_facts_json','p_source_facts'));assert(core.includes(negative.extracted_block));assert.equal(sha(core),negative.core_sha256);
const tests=[];for(const[i,spec]of specs.entries()){const file=base(i)+spec[2],r=cp.spawnSync(process.execPath,['--test','--test-reporter=tap',file],{cwd:repo,encoding:'utf8',maxBuffer:8e6}),b=Buffer.from(r.stdout+r.stderr);fs.writeFileSync(path.join(out,spec[2]+'.tap.txt'),b);assert.equal(r.status,0);assert.match(b.toString(),new RegExp('# pass '+spec[3]+'\\b'));assert.match(b.toString(),/# fail 0\b/);tests.push({file,cases:spec[3],output_sha256:sha(b)});}
const checks={source_only:true,native:false,mount_ready:false,before,after:seal(),actual_native_input_pins:pins,whole_owner_reverses:owners,unique_hunks:hunks,exact_shared_magnitude_extraction:true,tests,no_native_calls:true,remaining:['actual NHSP paid choice/NONE capture/prepared/report/Office consumers','negative-population resolution availability and order in full native projection','complete current root union/role/contract/registry/native financial/API acceptance']};fs.writeFileSync(path.join(out,'CHECKS.json'),JSON.stringify(checks,null,2)+'\n');console.log(JSON.stringify(checks));
